package glitch

import data.glitch_lib

is_switch_conditional(node) {
    node.ir_type == "ConditionalStatement"
    node.type == "SWITCH"
}

# Check if a switch is an immediate top-level switch in the chain (not nested inside statements)
top_level_switch_in_chain(node) {
    is_switch_conditional(node)
    node.is_top == true
}

# Check if a switch at the TOP level of a switch chain has a default at the SAME level
# We need to walk only the else_statement chain, not the entire subtree
switch_chain_lacks_default_top(switch_node) {
    top_level_switch_in_chain(switch_node)
    not has_default_in_chain(switch_node)
}

# Check if any switch in the else_statement chain has is_default = true
# This looks at the chain structure: node -> else_statement -> else_statement -> ...
has_default_in_chain(node) {
    node.is_default == true
} else {
    node.else_statement != null
    node.else_statement.ir_type == "ConditionalStatement"
    node.else_statement.type == "SWITCH"
    has_default_in_chain(node.else_statement)
}

# Boolean exhaustive check: if switch compares against true/false, it's exhaustive
is_boolean_exhaustive(switch_node) {
    # Check if the condition compares a variable against boolean values
    boolean_condition(switch_node.condition)
    has_true_and_false_branches(switch_node)
}

# Check if condition is comparing something to a boolean or is a boolean variable
boolean_condition(cond) {
    cond.ir_type == "Equal"
    cond.right.ir_type == "Boolean"
} else {
    cond.ir_type == "VariableReference"
} else {
    cond.ir_type == "Access"
}

# Check if switch chain has both true and false branches (exhaustive for boolean)
has_true_and_false_branches(switch_node) {
    # Collect all branch conditions in the chain and check for both true and false
    branch_values := {v | branch_val := get_branch_condition_value(switch_node, v)}
    branch_values[true]
    branch_values[false]
}

# Get the value from a branch condition (handles both direct boolean comparison and nested chains)
get_branch_condition_value(node, val) {
    node.condition.ir_type == "Equal"
    node.condition.right.ir_type == "Boolean"
    val := node.condition.right.value
} else {
    node.condition.ir_type == "Equal"
